<?phpfunction getDocumentRoot(): string{    return $_SERVER['DOCUMENT_ROOT'] . '/';}// Veriyi Ekrana Bas. _print($data);function _print($data, $jsonOutput = false){    if (!$jsonOutput) {        echo "<pre>";        print_r($data);        echo "</pre>";    } else {        ob_end_clean();        header('Content-Type: application/json; charset=utf-8');        echo json_encode($data);        die();    }}